import { motion } from 'framer-motion';
import { MapPin, ArrowRight, Sparkles } from 'lucide-react';
import { AreaData } from '../../data/types';
import { PriorityBadge } from '../ui/PriorityBadge';

interface AreaCardProps {
  area: AreaData;
  index: number;
  onClick: () => void;
  isSelected?: boolean;
}

export function AreaCard({ area, index, onClick, isSelected = false }: AreaCardProps) {
  const isKnown = area.type === 'known';

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.05 }}
      whileHover={{ y: -4 }}
      onClick={onClick}
      className={`group relative p-4 rounded-xl transition-all duration-300 cursor-pointer ${
        isSelected 
          ? 'bg-cyan-500/5 border-cyan-500/40 shadow-[0_0_60px_rgba(0,200,255,0.08)] card-selected'
          : 'bg-white/5 border border-white/5 hover:border-cyan-500/20 hover:shadow-[0_0_40px_rgba(0,200,255,0.03)]'
      }`}
    >
      {isSelected && (
        <div className="absolute inset-[-1px] rounded-xl bg-gradient-to-r from-cyan-500/30 via-transparent to-emerald-500/30 blur-sm"></div>
      )}
      
      <div className="absolute top-3 right-3 z-10">
        <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium flex items-center gap-1 ${
          isKnown 
            ? 'bg-blue-500/10 text-blue-400 border border-blue-500/20'
            : 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
        }`}>
          {!isKnown && <Sparkles className="w-2.5 h-2.5" />}
          {isKnown ? 'Known Area' : 'AI Candidate'}
        </span>
      </div>

      <div className="flex items-start gap-3">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <span className={`text-[10px] font-medium ${isKnown ? 'text-blue-400' : 'text-emerald-400'}`}>
              {isKnown ? `TEST CASE 0${index + 1}` : `CANDIDATE 0${index + 1}`}
            </span>
          </div>
          <div className="flex items-center gap-1.5">
            <MapPin className="w-3.5 h-3.5 text-cyan-400 flex-shrink-0" />
            <h3 className="text-sm font-semibold text-white truncate">{area.name}</h3>
          </div>
          <p className="text-xs text-gray-400 mt-0.5">{area.state}</p>
        </div>
        
        <div className={`w-12 h-12 rounded-lg overflow-hidden bg-gradient-to-br flex-shrink-0 ${
          area.id === 'dulhapur' ? 'from-blue-900/40 to-blue-700/20' :
          area.id === 'bhagoli' ? 'from-emerald-900/40 to-emerald-700/20' :
          area.id === 'candidate1' ? 'from-cyan-900/40 to-cyan-700/20' :
          'from-purple-900/40 to-purple-700/20'
        } flex items-center justify-center border border-white/5`}>
          <span className="text-[10px] text-gray-500">Sat</span>
        </div>
      </div>

      <div className="flex items-center justify-between mt-3 pt-2 border-t border-white/5">
        <div className="flex items-center gap-2">
          <PriorityBadge priority={area.priority} />
          <span className="text-[10px] text-gray-500">Score</span>
          <span className={`text-xs font-bold ${isSelected ? 'text-cyan-400' : 'text-cyan-400'}`}>
            {area.prospectivityScore}
          </span>
        </div>
        <ArrowRight className={`w-4 h-4 transition-all duration-300 flex-shrink-0 ${
          isSelected ? 'text-cyan-400' : 'text-gray-600 group-hover:text-cyan-400'
        }`} />
      </div>
    </motion.div>
  );
}
